  if (Y < 1 || N < 1) {
    throw new IllegalArgumentException("Both the start year and the position of the leap year to find must be positive.");
  }
  for (int i = 0; i < N - 1; i++) {
    Y += 1;
    if (Y % 4 == 0) {
      Y += 1;
    }
  }
  return Y;
}

