public static int countOilDeposits(char[][] grid) {
    // Initialize a hash set to store the positions of visited oil deposits
    Set<String> visitedPositions = new HashSet<>();
    // Initialize a variable to store the number of distinct oil deposits
    int distinctOilDeposits = 0;

    // Iterate over each row in the grid
    for (int i = 0; i < grid.length; i++) {
        // Iterate over each column in the row
        for (int j = 0; j < grid[i].length; j++) {
            // If the current position is an oil pocket
            if (grid[i][j] == '@') {
                // Check if the position has already been visited
                String position = i + ":" + j;
                if (!visitedPositions.contains(position)) {
                    // If not visited, visit the position and count it as an oil deposit
                    visitedPositions.add(position);
                    distinctOilDeposits++;
                }
            }
        }
    }

    // Return the number of distinct oil deposits
    return distinctOilDeposits;
}

