        return "can be travelled";
    }

    // Check if starting and ending n-tersections are adjacent
    boolean[][] visited = new boolean[n][n];
    boolean[][] explored = new boolean[n][n];
    Deque<int[]> queue = new ArrayDeque<>();
    queue.add(start);
    visited[start[0]][start[1]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Check if current n-tersection is not already explored
        if (!explored[current[0]][current[1]]) {
            explored[current[0]][current[1]] = true;

            // Enqueue adjacent n-tersections
            for (int i = 0; i < paths.length; i++) {
                int[] adj = paths[i];
                if (adj[0] == current[0] && adj[1] == current[1]) {
                    queue.add(adj);
                }
            }
        }
    }
    return "cannot be travelled";
}

