    // Find the minimum distance from node 0 to a node that has an apple
    int minDist = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && dist[i] < minDist) {
            minDist = dist[i];
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minDist * 2;
}

