public boolean splitArraySameAverage(int[] nums) {
    if (nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += nums[i];
    }

    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }

    int rightSum = sum - leftSum;

    if (leftSum == rightSum) {
        return true;
    }

    double leftAverage = leftSum / (nums.length / 2);
    double rightAverage = rightSum / (nums.length - nums.length / 2);

    return leftAverage == rightAverage;
}

