public int maxUniqueSplit(String s) {
    // Initialize a map to store the number of occurrences of each substring
    Map<String, Integer> substringCounts = new HashMap<>();

    // Initialize a set to store the unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Iterate over the characters in the string
    for (int i = 0; i < s.length(); i++) {
        // Check if the substring starting at index i is already in the set of unique substrings
        String substring = s.substring(i);
        if (!uniqueSubstrings.contains(substring)) {
            // If it is not in the set, add it and increment the number of occurrences in the map
            uniqueSubstrings.add(substring);
            substringCounts.put(substring, substringCounts.getOrDefault(substring, 0) + 1);
        }
    }

    // Return the maximum number of unique substrings
    return uniqueSubstrings.size();
}

