public int maxUniqueSplit(String s) {
int n = s.length();
int[][] dp = new int[n][n];

// Initialize the dp table with the length of each substring
for (int i = 0; i < n; i++) {
dp[i][i] = 1;
}

// Iterate over the substrings
for (int len = 1; len < n; len++) {
for (int i = 0; i + len < n; i++) {
int j = i + len;

// Check if the substring is unique
if (isUnique(s, i, j)) {
dp[i][j] = dp[i][j - 1] + 1;
}
}
}

return dp[0][n - 1];
}

